                "record|kind={kind}|tenant={tenant}|table=t_{:02}|pk={:08}|ver={:05}|tag=alpha,beta,gamma|payload=\"lorem ipsum lorem ipsum copied-substring copied-substring copied-substring UTF8-данные UTF8-日本語 UTF8-normal\"|ok={}|route=/api/v1/{service}/items/{:03}|note=Café-Δ\n",
                batch % 37,
                (epoch.wrapping_mul(104729) ^ batch.wrapping_mul(65537)) ^ 0x55aa33,
                (epoch * 97 + batch) % 1000,
                if (epoch + batch) % 11 == 0 { "false" } else { "true" },
                (epoch * 17 + batch * 13) % 200,
            );
            v.extend_from_slice(rec.as_bytes());

            let copyish = format!(
                "copy-range|session={epoch:02}-{batch:03}|AAAAABBBBBCCCCCDDDDDEEEEE|AAAAABBBBBCCCCCDDDDDEEEEE|AAAAABBBBBCCCCCDDDDDEEEEE|suffix={:04}\n",
                (epoch * 911 + batch * 37) % 10000
            );
            v.extend_from_slice(copyish.as_bytes());

            let json = format!(
                "{{\"type\":\"event\",\"name\":\"session.refresh\",\"tenant\":\"{tenant}\",\"kind\":\"{kind}\",\"attrs\":{{\"region\":\"{}\",\"rep\":\"rep rep rep rep rep\",\"path\":\"/v1/{service}/resource/{:04}\",\"blob\":\"aaaaaaaaabbbbbbbbbbccccccccccddddddddddeeeeeeeeee copied-fragment copied-fragment copied-fragment\"}}}}\n",
                match batch % 4 {
                    0 => "us-east",
                    1 => "eu-west",
                    2 => "ap-south",
                    _ => "sa-east",
                },
                (epoch * 257 + batch) % 4096
            );
            v.extend_from_slice(json.as_bytes());

            if batch % 8 == 0 {
                let hdr = format!(
                    "header version=3 source=node-{:03} partition={} watermark={} comment=\"repeated repeated repeated marker repeated repeated repeated marker\"\n",
                    (epoch * 97 + batch) % 97,
                    batch % 16,
                    1_700_000_000u64 + (epoch as u64) * 10_000 + batch as u64
                );
                v.extend_from_slice(hdr.as_bytes());
            }
        }

        v.extend_from_slice(format!("bundle-middle epoch={epoch:02} mode=records\n").as_bytes());
        v.extend_from_slice(&base_records);
        v.extend_from_slice(format!("bundle-end epoch={epoch:02} mode=perf\n").as_bytes());
        v.extend_from_slice(&base_perf);

        for stripe in 0..64u32 {
            let line = format!(
                "ts=2024-07-{day:02}T{hour:02}:{minute:02}:{second:02}Z app={app} env=prod cluster=c{cluster:02} pod={app}-{pod:05} req=req-{req:08} path=/v1/{app}/resource/{res:04} status={status} bytes={bytes} latency_ms={lat} user=u{user:06} msg=\"request completed with repeated common prefix\" tail=\"common common common suffix-{stripe:03}\"\n",
                day = (epoch + stripe) % 28 + 1,
                hour = stripe % 24,
                minute = (stripe * 7) % 60,
                second = (stripe * 11) % 60,
                app = match stripe % 6 {
                    0 => "payments",
                    1 => "search",
                    2 => "gateway",
                    3 => "worker",
                    4 => "notifier",
                    _ => "profile",
                },
                cluster = stripe % 12,
                pod = (epoch * 1000 + stripe) % 10000,
                req = epoch.wrapping_mul(2654435761).wrapping_add(stripe),
                res = (epoch * 131 + stripe * 17) % 4096,
                status = if stripe % 29 == 0 {
                    503
                } else if stripe % 17 == 0 {
                    429
                } else {
                    200
                },
                bytes = 700 + ((epoch * 123 + stripe * 19) % 8000),
                lat = 1 + ((epoch * 23 + stripe * 5) % 250),
                user = (epoch * 8191 + stripe * 17) % 500000
            );
            v.extend_from_slice(line.as_bytes());
        }
    }

    v
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let big = make_structured_compression_perf_corpus();
    let mut lines = Vec::new();

    for op in ["raw_deflate", "zlib_compress", "lz77_blocksplit_analysis"] {
        let path = format!("{}/{}.perf.bin", dir, op);
        fs::write(&path, &big).unwrap();
        lines.push(format!("perf {} {}", op, path));
    }

    lines
}
